// Build the single-document engine data bundle the browser loads through the
// C ABI memory path (pc_data_load_memory). Concatenates the compiled
// manifest/strings/game-data into the {"manifest","strings","game_data"} shape
// and writes it as a static asset Vite serves. Regenerated by the web app's
// predev/prebuild scripts; the output is gitignored.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const artifactDir = join(repoRoot, "data", "compiled", "current");
const outputDir = join(repoRoot, "apps", "web", "public");
const outputPath = join(outputDir, "poecraft-data.json");

function read(name) {
    return readFileSync(join(artifactDir, name), "utf8");
}

const manifest = read("manifest.json");
const strings = read("strings.json");
const gameData = read("game-data.json");
const bundle = `{"manifest":${manifest},"strings":${strings},"game_data":${gameData}}`;

mkdirSync(outputDir, { recursive: true });
writeFileSync(outputPath, bundle);
console.log(`wrote ${outputPath} (${(bundle.length / 1024 / 1024).toFixed(1)} MiB)`);
